<?php require_once __DIR__.'/config/db.php';$page_title='Contact — MediNova';$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&$message){$sent=true;}else{flash('error','Please complete the contact form correctly.');redirect('contact.php');}}require __DIR__.'/includes/store_header.php';?><section class="form-page"><div class="form-shell"><p class="kicker">GET IN TOUCH</p><h1>Talk to us.</h1><?php if($sent): ?><div class="admin-alert">Thanks, <?=e($name)?>. Your message has been received in this demo build.</div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-row"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div></div><div class="field"><label>Message</label><textarea name="message" rows="7" required></textarea></div><button class="btn btn-light">Send message ↗</button></form></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
